    out = [row[:] for row in grid]

    # Flood-fill background from the outside. Zero cells not reachable from
    # the edge are the enclosed regions; recolor those cells.
    seen = [[False] * w for _ in range(h)]
    stack = []
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and not seen[r][c]:
                seen[r][c] = True
                stack.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not seen[r][c]:
                seen[r][c] = True
                stack.append((r, c))

    while stack:
        r, c = stack.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and not seen[nr][nc]):
                seen[nr][nc] = True
                stack.append((nr, nc))

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and not seen[r][c]:
                out[r][c] = 8
    return out
