                    # Only fill frames containing an interior marker.
                    if not any(grid[r][c] == 2
                               for r in range(top + 1, bottom)
                               for c in range(left + 1, right)):
                        continue

                    interior_width = right - left - 1
                    color = {3: 8, 5: 4, 7: 3}.get(interior_width)
                    if color is None:
                        continue

                    for r in range(top + 1, bottom):
                        for c in range(left + 1, right):
                            if grid[r][c] == 0:
                                out[r][c] = color
    return out
